import { Button } from "@mui/material";
import { FileDownloadRounded } from "@mui/icons-material";

import {
  ForecastFilters,
  ForecastRecord,
} from "../types/forecast.types";

import { useForecastChart } from "../hooks/useForecast";

/**
 * =====================================================
 * EXPORT FORECAST  (NEW FEATURE)
 * =====================================================
 * Added in the redesign: lets users download the currently
 * filtered forecast (horizon × station × scenario) as a CSV file,
 * so the dashboard doubles as a reporting tool.
 */
interface ExportForecastProps {
  filters: ForecastFilters;
}

const ExportForecast = ({ filters }: ExportForecastProps) => {
  const { data, isLoading } = useForecastChart(filters);
  const records: ForecastRecord[] = data ?? [];

  const handleExport = () => {
    if (records.length === 0) return;

    const header = ["Entity", "Date", "Step", "Burn", "Supply", "Stockpile"];
    const rows = records.map((r) =>
      [
        r.entity_id,
        r.event_date,
        r.horizon_step,
        r.Input?.toFixed(3),
        r.Replenishment?.toFixed(3),
        r.Stockpile !== undefined && r.Stockpile !== null ? r.Stockpile.toFixed(3) : "",
      ].join(",")
    );

    const csv = [header.join(","), ...rows].join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `eskom-forecast-${filters.entityId}-${filters.horizon}-${filters.scenario}.csv`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
    <Button
      variant="outlined"
      size="small"
      startIcon={<FileDownloadRounded />}
      onClick={handleExport}
      disabled={isLoading || records.length === 0}
      sx={{ flexShrink: 0 }}
    >
      Export CSV
    </Button>
  );
};

export default ExportForecast;
